// Reverse index: synonym (lowercased) → canonical name.
const SYNONYM_INDEX: Map<string, string> = (() => {
  const m = new Map<string, string>();
  for (const [canonical, synonyms] of Object.entries(EQUIVALENCIES)) {
    for (const syn of synonyms) m.set(syn.toLowerCase(), canonical);
  }
  return m;
})();

/**
 * Fold a user-typed skill to its canonical form, if a synonym is known.
 * "Client Relations" → "Customer Service". Falls back to the input.
 */
export function canonicalize(skill: string): string {
  return SYNONYM_INDEX.get(skill.toLowerCase()) ?? skill;
}

/**
 * Expand a canonical skill into [canonical, ...synonyms]. Used by the
 * Skilmatch candidates query to widen the search: a recruiter looking
 * for "Customer Service" should also find candidates who wrote
 * "Client Relations" or "Customer Support" in their basket.
 *
 * If the input ISN'T canonical, first folds it through canonicalize()
 * then expands — so passing any synonym still returns the full family.
 */
export function expandWithSynonyms(skill: string): string[] {
  const canonical = canonicalize(skill);
  const synonyms = EQUIVALENCIES[canonical] || [];
  const all = new Set<string>([canonical, ...synonyms]);
  // Include the original input as well in case it differs from canonical.
  all.add(skill);
  return Array.from(all);
}
